{
  "claims": [
    {
      "claim": "Acyclovir, a polar adenine nucleoside lacking a phosphonate, had a human oral bioavailability of 0.2 (20%), exactly at the threshold; because the query has an ionized phosphonic acid, this evidence is only weakly transferable toward pass.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 1"
      ],
      "record_ids": [
        "Record 1-1"
      ]
    },
    {
      "claim": "Didanosine, an adenine nucleoside without a phosphonate, showed fasting oral bioavailability values of 22-28% and 38% with antacid; this suggests nucleoside analogs can exceed the threshold, but the query's phosphonate is a major additional polarity/charge liability.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 3",
        "Molecule 5"
      ],
      "record_ids": [
        "Record 3-1",
        "Record 3-2",
        "Record 5-1"
      ]
    },
    {
      "claim": "Fludarabine monophosphate was reported with 70% human oral bioavailability, but its phosphate ester is cleavable and the molecule differs from the phosphonic-acid query; transferability is limited.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 6"
      ],
      "record_ids": [
        "Record 6-1"
      ]
    },
    {
      "claim": "Valomaciclovir stearate and theophylline have high oral bioavailability but are, respectively, a lipophilic ester prodrug and a non-phosphonate xanthine; they provide little transferable evidence for the charged adenine phosphonate query.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 9",
        "Molecule 10"
      ],
      "record_ids": [
        "Record 9-1",
        "Record 10-1"
      ]
    },
    {
      "claim": "ATP, a highly polar adenine polyphosphate, had very low oral bioavailability (3.2-14.9%) in healthy volunteers, consistent with poor absorption of ionized adenine phosphate/phosphonate analogs.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 2"
      ],
      "record_ids": [
        "Record 2-1",
        "Record 2-2"
      ]
    },
    {
      "claim": "INVIRASE (saquinavir) had an average absolute oral bioavailability of 4%, but the structural similarity to the query is low and this only weakly supports a fail outcome.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 4"
      ],
      "record_ids": [
        "Record 4-1"
      ]
    },
    {
      "claim": "Didanosine fed-state bioavailability was 17-19%, below the threshold; the prandial condition differs from the query's fasted condition, so this evidence is only weakly supportive of fail.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 7"
      ],
      "record_ids": [
        "Record 7-1",
        "Record 7-2"
      ]
    },
    {
      "claim": "S-adenosylmethionine, a charged adenine derivative, mostly showed very low oral bioavailability in humans (0.58-2.6% for enteric-coated oral forms) and was repeatedly described as low, supporting poor absorption of ionized adenine-containing molecules.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 8"
      ],
      "record_ids": [
        "Record 8-1",
        "Record 8-2",
        "Record 8-4",
        "Record 8-6",
        "Record 8-7",
        "Record 8-8",
        "Record 8-9",
        "Record 8-10"
      ]
    },
    {
      "claim": "Two reports claimed high absolute oral bioavailability for 2 mg SAM (68.6% and 69%), but these are inconsistent with the majority of SAM studies and likely reflect method/endogenous-level issues; they are contradicted by the more abundant low-F data.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 8"
      ],
      "record_ids": [
        "Record 8-3",
        "Record 8-5"
      ]
    },
    {
      "claim": "The tosylate disulfate salt of SAM also showed an oral:IV AUC ratio of only 2.6% in healthy volunteers, reinforcing low oral absorption for charged adenine derivatives.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 14"
      ],
      "record_ids": [
        "Record 14-1"
      ]
    },
    {
      "claim": "Tenofovir, the closest acyclic adenine phosphonate analog of the query, has low oral bioavailability as the free acid, very low Caco-2 permeability (about 0.1 x 10^-6 cm/s), and only reaches about 25% F in humans when given as an ester prodrug; this is strong evidence that the unmasked phosphonate in the query will be below 20%.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2",
        "Record 13-3",
        "Record 13-4",
        "Record 13-9",
        "Record 13-15",
        "Record 13-17"
      ]
    },
    {
      "claim": "The prodrug adefovir dipivoxil, which masks the query's phosphonic acid as pivaloyloxymethyl esters, reached ~30% oral bioavailability in fasted humans; this indicates that the free phosphonic acid itself is expected to be less bioavailable, and the experiment does not measure the query directly.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-2"
      ]
    },
    {
      "claim": "Additional prodrug studies with adefovir dipivoxil show extensive intestinal esterase conversion, P-gp-mediated efflux, and asymmetrical Caco-2 transport, illustrating barriers that the unmasked phosphonate query would also face.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 11"
      ],
      "record_ids": [
        "Record 11-5",
        "Record 11-7",
        "Record 11-9"
      ]
    },
    {
      "claim": "Most diester prodrugs of the same adenine phosphonate gave mouse oral bioavailability values of 0-10%, showing that even after partial masking the free-acid phosphonate is usually poorly absorbed.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-1",
        "Record 12-5",
        "Record 12-9",
        "Record 12-12",
        "Record 12-16"
      ]
    },
    {
      "claim": "A few diester prodrugs of the same adenine phosphonate reached mouse oral bioavailability values of 22-26%, demonstrating that specific ester promoieties can pass the threshold, but the query is not such a prodrug.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-13",
        "Record 12-14",
        "Record 12-15"
      ]
    },
    {
      "claim": "Pradefovir, a related adefovir prodrug, showed extensive rat hepatic first-pass metabolism (86.7%), further supporting that adefovir-related phosphonates/prodrugs face substantial first-pass losses.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 16"
      ],
      "record_ids": [
        "Record 16-1"
      ]
    },
    {
      "claim": "Tenofovir is reported by some literature as a P-gp substrate; however Caco-2 studies in the same evidence set show low, non-effluxed permeability, so transporter effects do not rescue the low passive absorption of the phosphonate class.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 15",
        "Molecule 13"
      ],
      "record_ids": [
        "Record 15-1",
        "Record 13-20",
        "Record 13-21",
        "Record 13-22"
      ]
    }
  ],
  "final_prediction": "fail"
}

